  "routing.reason.required-mode-unsupported": ["This harness and model do not offer the required permission mode.", "Эта среда и модель не предлагают требуемый режим разрешений."],
  "routing.reason.effort-unsupported": ["The requested effort is not offered for this harness and model.", "Запрошенный уровень усилий недоступен для этой среды и модели."],
  "routing.reason.model-unsupported": ["Model support is confirmed unsupported for this account.", "Для этого аккаунта подтверждено, что модель не поддерживается."],
  "permission.network-sandbox-disabled": ["Network policy: disabled for sandboxed commands. Provider and control-plane traffic is separate.", "Сетевая политика: сеть команд в песочнице отключена. Трафик провайдера и управления рассматривается отдельно."],
  "permission.read-scope-restricted": ["Read scope restricted: commands can read only the working directory, system libraries and the Bun runtime, with no temp folders, home folder, ForgeOrbit data, other projects or credentials. Provider login is separate.", "Ограниченное чтение: команды читают только рабочую папку, системные библиотеки и среду Bun, без временных папок, домашней папки, данных ForgeOrbit, других проектов и учётных данных. Вход у провайдера отдельный."],
  "permission.title": ["What this mode really allows", "Что на самом деле разрешает этот режим"],
  "permission.sandbox-read-only": ["Read-only sandbox: Codex can inspect files but cannot modify them.", "Песочница только для чтения: Codex может смотреть файлы, но не изменять их."],
  "permission.sandbox-workspace-write": ["Workspace-write sandbox: Codex can write only inside the working directory and temp folders, and commands run inside the sandbox.", "Песочница с записью в рабочую область: Codex пишет только в рабочую папку и временные каталоги, команды выполняются внутри песочницы."],
  "permission.working-copy-development": ["Working-copy development: the Developer edits an isolated non-git copy of this project and runs offline local checks using private scratch space. The original project stays unchanged until you approve applying changes.", "Разработка в рабочей копии: разработчик правит изолированную копию проекта вне Git и запускает локальные офлайн-проверки с выделенным временным пространством. Исходный проект не меняется, пока вы не одобрите применение изменений."],
  "permission.sandbox-danger-full-access": ["No sandbox: Codex runs with your user's full permissions.", "Без песочницы: Codex работает с полными правами вашего пользователя."],
  "permission.approval-never-asked": ["Approval prompts never appear: Codex runs non-interactively.", "Запросы подтверждения не появляются: Codex работает неинтерактивно."],
  "permission.network-codex-config": ["Network access follows your Codex configuration and may be on. ForgeOrbit does not restrict it, and a prompt instruction is not a restriction.", "Доступ к сети определяется вашей настройкой Codex и может быть включён. ForgeOrbit его не ограничивает, а указание в промпте ограничением не является."],
  "permission.network-unrestricted": ["Network access is unrestricted.", "Доступ к сети не ограничен."],
  "permission.layout-linked-worktree": ["Linked Git worktree: Git metadata is outside the workspace. Auto keeps its sandbox; external writes require a new Owner decision.", "Связанное дерево Git: метаданные вне рабочей папки. Auto сохраняет песочницу; внешняя запись требует нового решения Owner."],
  "permission.layout-repo-subfolder": ["Git repository subdirectory: Git metadata is outside the workspace. Auto keeps its sandbox; external writes require a new Owner decision.", "Подпапка Git: метаданные вне рабочей папки. Auto сохраняет песочницу; внешняя запись требует нового решения Owner."],
  "permission.layout-unknown": ["Workspace layout is Unknown. Launch is blocked until it can be verified.", "Расположение рабочей области Unknown. Запуск заблокирован до проверки."],
  "permission.owner-decision-required": ["A new Owner decision is required. Nothing will launch with broader permissions automatically.", "Нужно новое решение Owner. Запуска с расширением прав автоматически не будет."],
  "permission.full-access-consent": ["I explicitly authorize full user filesystem and network access without a sandbox for this run.", "Я явно разрешаю этому запуску полные права пользователя на файловую систему и сеть без песочницы."],
  "pmRouting.title": ["Execution suggestion for Owner review", "Предложение исполнителя для проверки Owner"],
  "pmRouting.load": ["Review executor options", "Проверить варианты исполнителя"],
  "pmRouting.note": ["Approving assigns only the proposed worker. Harness and model remain suggestions; starting requires a separate execution review and confirmation.", "Подтверждение назначает только предложенного сотрудника. Harness и модель остаются рекомендациями; запуск требует отдельной проверки и подтверждения."],
  "pmRouting.none": ["No eligible executor. Availability remains Unknown or blocked; assignment does not authorize execution.", "Нет подходящего исполнителя. Доступность Unknown или заблокирована; назначение не разрешает запуск."],
  "pmRouting.confirm": ["I reviewed the executor evidence and permission limits for this assignment.", "Я проверил evidence исполнителя и ограничения прав для этого назначения."],
  "permission.predicted": ["Predicted before the run: the worktree is created when it starts.", "Прогноз до запуска: рабочее дерево создаётся при старте."],
