  "access.label": ["Access mode", "Режим доступа"],
  "access.mode.workspace": ["Workspace", "Рабочая область"],
  "access.mode.isolated": ["Isolated", "Изолированный"],
  "access.mode.full-computer": ["Full Computer", "Весь компьютер"],
  "access.desc.workspace": ["Operates within the selected project's normal workspace.", "Работает в обычной рабочей области выбранного проекта."],
  "access.desc.isolated": ["Operates in a disposable environment with explicit inputs, no network by default, and no automatic write-back.", "Работает во временной изолированной среде с явно переданными файлами, без сети по умолчанию и без автозаписи в проект."],
  "access.desc.full-computer": ["Lets the Owner grant specific capabilities outside the workspace (selected origin, application, or window). Selecting the mode grants nothing.", "Позволяет Owner отдельно разрешать действия вне рабочей области (выбранный домен, приложение или окно). Выбор режима сам по себе ничего не разрешает."],
  "access.disclosure.title": ["Launch review & boundaries", "Обзор прав и границ запуска"],
  "access.disclosure.grants_nothing": ["Selecting a mode itself grants nothing.", "Сам выбор режима не выдаёт никаких разрешений."],
  "access.disclosure.effective_workspace": ["Effective workspace", "Эффективная рабочая область"],
  "access.disclosure.workspace.project-folder": ["Project folder (direct writes affect your repository)", "Папка проекта (прямая запись меняет репозиторий)"],
